import { PRODUCTS, findOption, type ProductId } from "@/config/catalog";
import { PREVIEW_IMAGES, previewCoverage } from "@/config/previewImages";

/** Markdown list of which concept images exist and which are missing (docs/PREVIEW_IMAGES.md). */
export function previewCoverageMarkdown(): string {
  const rows = previewCoverage();
  const have = rows.filter((r) => r.imageId).length;
  const lines: string[] = [
    "# Concept images: what exists and what is missing",
    "",
    "<!-- Generated by `npm run previews:report` from src/config/previewImages.ts. Do not edit by hand. -->",
    "",
    `**${have} of ${rows.length}** orderable combinations (product × stitch × material × colour) have a concept image.`,
    "Customers who pick a missing combination see “No concept image yet for this combination” instead of a",
    "picture of something else, and their order still records the exact options. Size is shown by the",
    "dimensions, so one image covers both sizes unless a size-specific image is added.",
    "",
  ];
  for (const productId of ["bag", "scarf"] as ProductId[]) {
    const p = PRODUCTS[productId];
    const list = rows.filter((r) => r.product === productId);
    lines.push(`## ${p.name} (${list.filter((r) => r.imageId).length} of ${list.length})`, "");
    lines.push("| Stitch | Material | Colour | Image |", "|---|---|---|---|");
    for (const r of list) {
      lines.push(
        `| ${findOption(p.stitches, r.stitch)?.label} | ${findOption(p.materials, r.material)?.label} | ${
          findOption(p.colors, r.color)?.label
        } | ${r.imageId ? `\`${r.imageId}\`` : "**missing**"} |`,
      );
    }
    lines.push("");
  }
  lines.push("## Image files", "", "| Image id | Supplied file | Size |", "|---|---|---|");
  for (const i of PREVIEW_IMAGES) lines.push(`| \`${i.id}\` | ${i.sourceFile} | ${i.size ?? "all sizes"} |`);
  lines.push("");
  return lines.join("\n");
}
